        if (n.max === Infinity) {
          if (n.min === 0) rec({ t: 'star', child: n.child })
          else rec({ t: 'star', child: n.child })
        } else {
          for (let k = 0; k < n.max - n.min; k++) rec({ t: 'quest', child: n.child })
        }
